package com.minova.cloud;
import android.app.*;import android.os.*;import android.graphics.*;import android.text.TextUtils;import android.util.LruCache;import android.view.*;import android.widget.*;import org.json.JSONObject;import java.io.*;import java.net.HttpURLConnection;import java.util.*;import java.util.concurrent.*;
final class PhotoGalleryDialog extends Dialog {
    static final class Photo {final JSONObject original,item,share;Photo(JSONObject original,JSONObject item,JSONObject share){this.original=original;this.item=item;this.share=share;}}
    interface Action {void run(JSONObject item,boolean save);}
    final Activity owner;final CloudApi api;final List<Photo> photos;final Action action;final ExecutorService io=Executors.newFixedThreadPool(3);final Handler main=new Handler(Looper.getMainLooper());
    final LruCache<Integer,Bitmap> cache=new LruCache<>(32*1024){@Override protected int sizeOf(Integer key,Bitmap bitmap){return Math.max(1,bitmap.getByteCount()/1024);}};
    final Map<Integer,Future<?>> jobs=new HashMap<>();final Map<Integer,Integer> tokens=new HashMap<>();final ConcurrentHashMap<Integer,HttpURLConnection> connections=new ConcurrentHashMap<>();final File temporary;
    ZoomPhotoView image;TextView title,counter,status;Button previous,next,fit;int index,sequence;volatile boolean closed;
    PhotoGalleryDialog(Activity owner,CloudApi api,List<Photo> photos,int index,Action action){super(owner);this.owner=owner;this.api=api;this.photos=Collections.unmodifiableList(new ArrayList<>(photos));this.index=index;this.action=action;temporary=new File(new File(owner.getCacheDir(),"photo-viewer"),UUID.randomUUID().toString());}
    int dp(float value){return MinovaUi.dp(owner,value);}TextView label(String text,int size,int color){TextView view=new TextView(owner);view.setText(text);view.setTextSize(size);view.setTextColor(color);return view;}
    Button button(String text,String description,Runnable onClick){Button view=new Button(owner);view.setText(text);view.setContentDescription(description);view.setAllCaps(false);view.setTextColor(MinovaUi.WHITE);view.setTextSize(15);view.setMinWidth(0);view.setMinimumWidth(0);view.setPadding(dp(8),0,dp(8),0);view.setBackground(MinovaUi.touch(owner,MinovaUi.SURFACE,MinovaUi.LINE,8));view.setOnClickListener(v->onClick.run());return view;}
    LinearLayout row(){LinearLayout view=new LinearLayout(owner);view.setGravity(Gravity.CENTER_VERTICAL);return view;}
    @Override protected void onCreate(Bundle state){super.onCreate(state);requestWindowFeature(Window.FEATURE_NO_TITLE);getWindow().setBackgroundDrawableResource(android.R.color.transparent);getWindow().setStatusBarColor(MinovaUi.NIGHT);getWindow().setNavigationBarColor(MinovaUi.NIGHT);LinearLayout root=new LinearLayout(owner);root.setOrientation(LinearLayout.VERTICAL);root.setBackgroundColor(MinovaUi.NIGHT);setContentView(root);
        LinearLayout top=row();top.setPadding(dp(18),dp(10),dp(12),dp(10));LinearLayout caption=new LinearLayout(owner);caption.setOrientation(LinearLayout.VERTICAL);title=label("",16,MinovaUi.WHITE);title.setMaxLines(1);title.setEllipsize(TextUtils.TruncateAt.MIDDLE);counter=label("",12,MinovaUi.MUTED);counter.setAccessibilityLiveRegion(View.ACCESSIBILITY_LIVE_REGION_POLITE);caption.addView(title);caption.addView(counter);top.addView(caption,new LinearLayout.LayoutParams(0,-2,1));top.addView(button("✕","Close photo viewer",this::dismiss),new LinearLayout.LayoutParams(dp(46),dp(46)));root.addView(top);
        FrameLayout stage=new FrameLayout(owner);image=new ZoomPhotoView(owner,()->move(-1),()->move(1));stage.addView(image,new FrameLayout.LayoutParams(-1,-1));status=label("Loading photo…",14,MinovaUi.MUTED);status.setGravity(Gravity.CENTER);status.setPadding(dp(24),dp(16),dp(24),dp(16));stage.addView(status,new FrameLayout.LayoutParams(-1,-2,Gravity.CENTER));root.addView(stage,new LinearLayout.LayoutParams(-1,0,1));
        LinearLayout controls=row();controls.setGravity(Gravity.CENTER);controls.setPadding(dp(12),dp(12),dp(12),dp(8));previous=button("‹","Previous photo",()->move(-1));next=button("›","Next photo",()->move(1));Button minus=button("−","Zoom out",()->image.zoomTo(image.zoom/1.5f,image.getWidth()/2f,image.getHeight()/2f));fit=button("Fit","Fit photo",()->image.fit());Button plus=button("+","Zoom in",()->image.zoomTo(image.zoom*1.5f,image.getWidth()/2f,image.getHeight()/2f));for(Button item:new Button[]{previous,minus,fit,plus,next}){LinearLayout.LayoutParams layout=new LinearLayout.LayoutParams(dp(item==fit?62:48),dp(46));layout.setMargins(dp(3),0,dp(3),0);controls.addView(item,layout);}root.addView(controls);image.changed=()->fit.setText(image.zoom==1?"Fit":Math.round(image.zoom*100)+"%");
        LinearLayout actions=row();actions.setPadding(dp(18),dp(4),dp(18),dp(14));for(boolean save:new boolean[]{true,false}){Button item=button(save?"Save to phone":"Open with…",save?"Save current photo to phone":"Open current photo with another app",()->action.run(photos.get(index).original,save));LinearLayout.LayoutParams layout=new LinearLayout.LayoutParams(0,dp(44),1);layout.setMargins(dp(4),0,dp(4),0);actions.addView(item,layout);}root.addView(actions);
        if(Build.VERSION.SDK_INT>=30){getWindow().setDecorFitsSystemWindows(false);root.setOnApplyWindowInsetsListener((v,insets)->{android.graphics.Insets bars=insets.getInsets(WindowInsets.Type.systemBars());v.setPadding(bars.left,bars.top,bars.right,bars.bottom);return insets;});}
        setOnDismissListener(d->cleanup());
    }
    @Override public void show(){super.show();getWindow().setLayout(-1,-1);showPhoto(index);}
    void move(int delta){int target=index+delta;if(target>=0&&target<photos.size())showPhoto(target);}
    void showPhoto(int position){if(closed)return;index=position;Photo photo=photos.get(index);title.setText(photo.original.optString("name"));counter.setText((index+1)+" of "+photos.size());previous.setEnabled(index>0);next.setEnabled(index<photos.size()-1);image.animate().cancel();image.setImageBitmap(null);image.setAlpha(1);status.setText("Loading photo…");status.setVisibility(View.VISIBLE);
        for(Integer key:new ArrayList<>(jobs.keySet()))if(Math.abs(key-index)>1){jobs.remove(key).cancel(true);tokens.remove(key);HttpURLConnection connection=connections.remove(key);if(connection!=null)connection.disconnect();}
        Bitmap cached=cache.get(index);if(cached!=null)display(cached);else request(index);
    }
    void display(Bitmap bitmap){image.setImageBitmap(bitmap);status.setVisibility(View.GONE);if(ValueAnimatorEnabled()) {image.setAlpha(0);image.animate().alpha(1).setDuration(160).start();}for(int nearby:new int[]{index-1,index+1})if(nearby>=0&&nearby<photos.size()&&cache.get(nearby)==null)request(nearby);}
    boolean ValueAnimatorEnabled(){return Build.VERSION.SDK_INT<26||android.animation.ValueAnimator.areAnimatorsEnabled();}
    void request(int position){if(closed||jobs.containsKey(position))return;int token=++sequence;tokens.put(position,token);FutureTask<Void> job=new FutureTask<>(()->{
        File file=new File(temporary,position+"-"+token+".part");Bitmap bitmap=null;String error=null;HttpURLConnection connection=null;
        try{if(!temporary.isDirectory()&&!temporary.mkdirs())throw new IOException("Could not prepare photo preview.");Photo photo=photos.get(position);connection=api.connection(api.fileRoute(photo.item,photo.share,false),"GET",true);connections.put(position,connection);if(connection.getResponseCode()!=200)throw new IOException("This photo is no longer available. Refresh your library.");if(connection.getContentLengthLong()>128L*1024*1024)throw new IOException("This original is too large to preview. Use Open with…");
            try(InputStream input=connection.getInputStream();OutputStream output=new FileOutputStream(file)){byte[] buffer=new byte[64*1024];int count;long total=0;while((count=input.read(buffer))!=-1){if(closed||Thread.currentThread().isInterrupted())throw new InterruptedIOException();total+=count;if(total>128L*1024*1024)throw new IOException("This original is too large to preview. Use Open with…");output.write(buffer,0,count);}}
            bitmap=PhotoBitmaps.decodeFile(file,2048);if(bitmap==null)throw new IOException("This format needs another viewer. Use Open with…, or continue to the next photo.");
        }catch(OutOfMemoryError failure){error="Not enough memory to preview this original. Use Open with…";}catch(Exception failure){error=failure.getMessage();}finally{if(connection!=null){connections.remove(position,connection);connection.disconnect();}file.delete();if(closed)temporary.delete();}
        final Bitmap loaded=bitmap;final String message=error;main.post(()->{if(closed||!Integer.valueOf(token).equals(tokens.get(position)))return;jobs.remove(position);tokens.remove(position);if(loaded!=null){cache.put(position,loaded);if(index==position)display(loaded);}else if(index==position){status.setVisibility(View.VISIBLE);status.setText(message==null?"Could not load this photo. Use Open with…, or try the next photo.":message);}});return null;
    });jobs.put(position,job);io.execute(job);}
    void cleanup(){if(closed)return;closed=true;for(Future<?> job:jobs.values())job.cancel(true);jobs.clear();tokens.clear();for(HttpURLConnection connection:connections.values())connection.disconnect();connections.clear();io.shutdownNow();main.removeCallbacksAndMessages(null);image.setImageBitmap(null);cache.evictAll();temporary.delete();}
    @Override public boolean onKeyUp(int code,KeyEvent event){if(code==KeyEvent.KEYCODE_DPAD_LEFT){move(-1);return true;}if(code==KeyEvent.KEYCODE_DPAD_RIGHT){move(1);return true;}return super.onKeyUp(code,event);}
}
